249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner != null) {
254	            Pet pet = owner.getPet(petId);
255	            if (pet != null) {
256	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
257	            }
258	        }
259	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	    }
261	
262	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
263	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
264	
265	    /**
266	     * Required national-number length per country code: '+61' (Australia) expects 9 national
267	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
268	     * national part is not the required length is rejected.
269	     */
270	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
271	        "+61", 9, "+1", 10);
272	
273	    /**
274	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
275	     * code are kept when present; otherwise country code '+61' is assumed and a single
276	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
277	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
278	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
279	     * Returns {@code null} when the number cannot form a valid E.164 value.
280	     */
281	    private static String normalizeTelephone(String telephone) {
282	        if (telephone == null) {
283	            return null;
284	        }
285	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
286	        String e164;
287	        if (cleaned.startsWith("+")) {
288	            e164 = cleaned;
289	        } else {
290	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
291	            e164 = "+61" + national;
292	        }
293	        if (!E164_PATTERN.matcher(e164).matches()) {
294	            return null;
295	        }
296	        return hasValidNationalNumberLength(e164) ? e164 : null;
297	    }
298	
299	    /**
300	     * Whether the national number of a well-formed E.164 value has the length required for its
301	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
302	     * per-country length rule and are accepted.
303	     */
304	    private static boolean hasValidNationalNumberLength(String e164) {
305	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
306	            String countryCode = entry.getKey();
307	            if (e164.startsWith(countryCode)) {
308	                return e164.length() - countryCode.length() == entry.getValue();
309	            }
310	        }
311	        return true;
312	    }
313	
314	    /**
315	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
316	     * code, membership number, household id, namesake count and household member count. Each is
317	     * derived from the owner's already-normalized fields and the existing owner population, so this
318	     * must run before the owner is saved, while the counts still exclude the owner being created.
319	     */
320	    private void assignRegistrationAttributes(Owner owner) {
321	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
322	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
323	        owner.setHouseholdId(householdId(owner));
324	        owner.setNamesakeCount(countNamesakes(owner));
325	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
326	    }
327	
328	    /**
329	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
330	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
331	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
332	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
333	     */
334	    private String generateCustomerCode(String city, String lastName) {
335	        String city3 = firstThreeLetters(city);
336	        String last3 = firstThreeLetters(lastName);
337	        int sequence = countOwnersInCity(city) + 1;
338	        return String.format("%s-%s-%04d", city3, last3, sequence);
339	    }
340	
341	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
342	    private static String firstThreeLetters(String value) {
343	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
344	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
345	    }
346	
347	    /**
348	     * The number of existing owners registered in {@code city}, compared case-insensitively
349	     * with collapsed whitespace.
350	     */
351	    private int countOwnersInCity(String city) {
352	        String normalized = normalizeHouseholdField(city);
353	        return (int) this.clinicService.findAllOwners().stream()
354	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
355	            .count();
356	    }
357	
358	    /**
359	     * The effective registration date to store for a new owner: the date supplied on the request
360	     * when present, otherwise the current server date, in either case rolled forward to a business
361	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
362	     * This single point of resolution is what every registration-date-derived value (the stored
363	     * date, the membership number's year segment, the per-day create-limit) is computed from.
364	     */
365	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
366	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
367	        return toBusinessDay(date);
368	    }
369	
370	    /**
371	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
372	     * following Monday; a weekday is returned unchanged.
373	     */
374	    private static LocalDate toBusinessDay(LocalDate date) {
375	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
376	            date = date.plusDays(1);
377	        }
378	        return date;
379	    }
380	
381	    /**
382	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
383	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
384	     */
385	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
386	        String yy = String.format("%02d", registrationDate.getYear() % 100);
387	        return customerCode + "-M" + yy;
388	    }
389	
390	    /**
391	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
392	     * last name, compared case-insensitively.
393	     */
394	    private int countNamesakes(Owner owner) {
395	        String firstName = normalizeHouseholdField(owner.getFirstName());
396	        String lastName = normalizeHouseholdField(owner.getLastName());
397	        return (int) this.clinicService.findAllOwners().stream()
398	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
399	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
400	            .count();
401	    }
402	
403	    /**
404	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
405	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
406	     * unusually high daily signup volume.
407	     */
408	    private boolean isBulkSignupWarning() {
409	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
410	    }
411	
412	    /** The number of existing owners whose registration date is {@code date}. */
413	    private int countOwnersRegisteredOn(LocalDate date) {
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(existing -> date.equals(existing.getRegistrationDate()))
416	            .count();
417	    }
418	
419	    /**
420	     * Whether {@code owner} collides with an existing owner on any of the identity dimensions checked
421	     * at creation: its telephone, its email, or — unless the request opts into household sharing — its
422	     * household (same last name and address). A match on any single dimension makes this a duplicate.
423	     * This is the one gate every duplicate rule flows through, so a create that trips it is rejected
424	     * with {@code 409 CONFLICT}.
425	     */
426	    private boolean isDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
427	        if (isTelephoneInUse(owner.getTelephone())) {
428	            return true;
429	        }
430	        if (owner.getEmail() != null && isEmailInUse(owner.getEmail())) {
431	            return true;
432	        }
433	        return !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner);
434	    }
435	
436	    /** Whether any existing owner already uses the given (E.164) telephone number. */
437	    private boolean isTelephoneInUse(String telephone) {
438	        return this.clinicService.findAllOwners().stream()
439	            .map(Owner::getTelephone)
440	            .filter(existing -> existing != null)
441	            .map(OwnerRestControllerV1::normalizeTelephone)
442	            .filter(existing -> existing != null)
443	            .anyMatch(telephone::equals);
444	    }
445	
446	    /** Whether any existing owner already uses the given email, compared case-insensitively (lower-cased). */
447	    private boolean isEmailInUse(String email) {
448	        String normalized = email.trim().toLowerCase(Locale.ROOT);
449	        return this.clinicService.findAllOwners().stream()
450	            .map(Owner::getEmail)
451	            .filter(existing -> existing != null)
452	            .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
453	            .anyMatch(normalized::equals);
454	    }
455	
456	    /** Common street-type abbreviations expanded during address normalization. */
457	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
458	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
459	
460	    /**
461	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
462	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
463	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
464	     * string when {@code address} is null or blank after normalization.
465	     */
466	    private static String normalizeAddress(String address) {
467	        if (address == null) {
468	            return "";
469	        }
470	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
471	        if (collapsed.isEmpty()) {
472	            return "";
473	        }
474	        StringBuilder sb = new StringBuilder(collapsed.length());
475	        for (String token : collapsed.split(" ")) {
476	            if (sb.length() > 0) {
477	                sb.append(' ');
478	            }
479	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
480	        }
481	        return sb.toString();
482	    }
483	
484	    /**
485	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
486	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
487	     */
488	    private static String normalizeHouseholdField(String value) {
489	        if (value == null) {
490	            return "";
491	        }
492	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
493	    }
494	
495	    /**
496	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
497	     * same address compared case-insensitively with collapsed whitespace.
498	     */
499	    private List<Owner> findHousemates(Owner owner) {
500	        String lastName = normalizeHouseholdField(owner.getLastName());
501	        String address = normalizeHouseholdField(owner.getAddress());
502	        return this.clinicService.findAllOwners().stream()
503	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
504	                && normalizeHouseholdField(existing.getAddress()).equals(address))
505	            .toList();
506	    }
507	
508	    /**
509	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
510	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
511	     */
512	    private boolean isHouseholdInUse(Owner owner) {
513	        return !findHousemates(owner).isEmpty();
514	    }
515	
516	    /**
517	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
518	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
519	     */
520	    private int countHouseholdMembers(Owner owner) {
521	        return findHousemates(owner).size() + 1;
522	    }
523	
524	    /**
525	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
526	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
527	     * deterministically from those normalized fields so housemates always resolve to the same value,
528	     * regardless of registration order.
529	     */
530	    private static String householdId(Owner owner) {
531	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
532	            + normalizeHouseholdField(owner.getAddress());
533	        try {
534	            byte[] digest = MessageDigest.getInstance("SHA-256")
535	                .digest(key.getBytes(StandardCharsets.UTF_8));
536	            StringBuilder sb = new StringBuilder(24);
537	            for (int i = 0; i < 12; i++) {
538	                sb.append(String.format("%02X", digest[i]));
539	            }
540	            return sb.toString();
541	        }
542	        catch (NoSuchAlgorithmException e) {
543	            throw new IllegalStateException("SHA-256 not available", e);
544	        }
545	    }
